internal sealed class NativeProtectionCoordinator:IDisposable {
 [DllImport("shell32.dll")]static extern int SHGetKnownFolderPath(ref Guid id,uint flags,IntPtr token,out IntPtr path);
 sealed class Candidate{internal string Path;internal int Attempt;internal long Length=-1;internal DateTime Written,Seen;}
 sealed class Job{internal DateTime? CancelRequested;internal int Attempt;internal string CurrentFile="";internal string Id,Mode,Path,Stamp,State="queued";internal long Bytes;internal long Checked,Skipped,Findings,Quarantined;internal DateTime Started=DateTime.UtcNow,ProgressAt=DateTime.UtcNow;}
 readonly object gate=new object();readonly Dictionary<string,Candidate> waiting=new Dictionary<string,Candidate>(StringComparer.OrdinalIgnoreCase);readonly Dictionary<string,Job> jobs=new Dictionary<string,Job>();readonly Dictionary<string,string> scanned=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);readonly List<object> events=new List<object>();readonly List<object> findings=new List<object>();readonly Action<string> notify;
 NativeProtectionRuntime runtime;FileSystemWatcher watcher;Timer timer;string downloads,error="Preparing the scanner…",updateError="";bool available,monitoring,disposed,checking,initializing;long signatures,builtAt;DateTime lastRestart=DateTime.MinValue;Job manual,lastAuto;int activeDownloads,generation;DateTime lastReconcile=DateTime.MinValue;
 internal NativeProtectionCoordinator(Action<string> notify){this.notify=notify;Task.Run((Action)Initialize);}
#if SENTINEL_PROTECTION_QUALIFICATION
 readonly string qualificationDownloads,qualificationVault;
 internal NativeProtectionCoordinator(Action<string> notify,string testDownloads,string testVault){this.notify=notify;qualificationDownloads=testDownloads;qualificationVault=testVault;Task.Run((Action)Initialize);}
#endif
 static string Downloads(){IntPtr value;var id=new Guid("374DE290-123F-4565-9164-39C4925E467B");if(SHGetKnownFolderPath(ref id,0,IntPtr.Zero,out value)!=0)throw new IOException();try{return Marshal.PtrToStringUni(value);}finally{Marshal.FreeCoTaskMem(value);}}
 void Initialize(){try{downloads=Downloads();
#if SENTINEL_PROTECTION_QUALIFICATION
if(qualificationDownloads!=null)downloads=qualificationDownloads;
#endif
if(downloads.StartsWith("E:",StringComparison.OrdinalIgnoreCase)||!Directory.Exists(downloads)||!NativeScanPolicy.NoLinks(downloads))throw new IOException();bool enabled=true;using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey("Software\\Sentinel\\Protection")){if(key!=null)enabled=Convert.ToInt32(key.GetValue("DownloadMonitoring",1))!=0;}SetMonitoring(enabled);lock(gate){if(disposed)return;timer=new Timer(Tick,null,2000,2000);}StartRuntime();}catch{lock(gate)error="Downloads protection could not initialize. Check that your Downloads folder is available.";}}
 void StartRuntime(){lock(gate){if(disposed)return;available=false;initializing=true;error="Preparing the scanner…";lastRestart=DateTime.UtcNow;string vault=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Sentinel-School-Demo","inspection-vault");
#if SENTINEL_PROTECTION_QUALIFICATION
if(qualificationVault!=null)vault=qualificationVault;
#endif
int current=++generation;runtime=new NativeProtectionRuntime(downloads,vault,value=>{lock(gate){if(current==generation&&!disposed)Receive(value);}},message=>{lock(gate){if(current==generation&&!disposed)Failed(message);}});runtime.Start();}}
 string lastFailureNotification;
 void Failed(string message){lock(gate){if(disposed)return;available=false;initializing=false;error=message;foreach(var job in jobs.Values){job.State="failed";if(job.Mode=="download"&&!string.IsNullOrEmpty(job.Path))Arrived(job.Path);}jobs.Clear();activeDownloads=0;Add("warning","Scanner unavailable",message);if(notify!=null&&lastFailureNotification!=message){lastFailureNotification=message;notify(message);}}}
 void Receive(Dictionary<string,object> value){lock(gate){if(disposed)return;string type=Convert.ToString(value["type"]);if(type=="ready"){signatures=Convert.ToInt64(value["signatures"]);builtAt=Convert.ToInt64(value["builtAt"]);if(signatures<=0||builtAt<=0)throw new IOException();available=true;initializing=false;lastFailureNotification=null;error="";updateError=runtime.UpdateError;if(monitoring)Reconcile();return;}
  string id=value.ContainsKey("id")?value["id"] as string:null;Job job;if(id==null||!jobs.TryGetValue(id,out job))throw new IOException("Unknown scanner job.");
  if(type=="error"){job.State="failed";Finish(job,"Scanner could not accept this job. Retry the scan.");return;}
  if(type=="finding"){var file=value["file"] as Dictionary<string,object>;if(file==null)throw new IOException();string path=file["path"] as string,state=file["state"] as string;if(path==null||path.Length>2048||state==null)throw new IOException();var signals=file["signals"] as System.Collections.ArrayList;if(signals==null||signals.Count>8||signals.Cast<object>().Any(v=>!(v is string)||((string)v).Length>256))throw new IOException();string quarantine=file["quarantine"] as string;string quarantineState=file["quarantineState"] as string;if(quarantine!=null&&!System.Text.RegularExpressions.Regex.IsMatch(quarantine,"^[a-f0-9]{32}\\.qtn$"))throw new IOException();findings.Insert(0,new{path,signals=signals.Cast<string>().ToArray(),state,quarantine,quarantineState});if(findings.Count>16)findings.RemoveAt(16);if(job.Mode=="download"||job.Mode=="reconcile"){string title=quarantineState=="quarantined"?"Threat quarantined":state=="signature_match"?"Threat signature detected":state=="test_match"?"Test pattern detected":"File needs review";Add(state=="signature_match"?"threat":"warning",title,Path.GetFileName(path)+" · "+string.Join(", ",signals.Cast<string>().ToArray()));if(state=="signature_match"&&notify!=null)notify(title+". Open Sentinel for details.");}return;}
  if(type!="progress")throw new IOException();string next=value["state"] as string;if(!new[]{"scanning","paused","completed","incomplete","cancelled"}.Contains(next))throw new IOException();long count=Convert.ToInt64(value["checked"]),skip=Convert.ToInt64(value["skipped"]),found=Convert.ToInt64(value["findings"]),quarantined=Convert.ToInt64(value["quarantined"]);if(count<job.Checked||skip<job.Skipped||found<job.Findings||quarantined<job.Quarantined||count+skip>1000001||quarantined>found)throw new IOException();long bytes=Convert.ToInt64(value["bytes"]);string current=value["currentFile"] as string;if(bytes<job.Bytes||(current!=null&&current.Length>1024))throw new IOException();job.Bytes=bytes;job.CurrentFile=current??"";job.Checked=count;job.Skipped=skip;job.Findings=found;job.Quarantined=quarantined;job.State=job.CancelRequested.HasValue&&new[]{"scanning","paused"}.Contains(next)?"stopping":next;job.ProgressAt=DateTime.UtcNow;if(new[]{"completed","incomplete","cancelled"}.Contains(next))Finish(job,null);
 }}
 void Finish(Job job,string failure){jobs.Remove(job.Id);if(job.Mode=="reconcile"&&new[]{"completed","incomplete"}.Contains(job.State))error="";if(job.Mode=="download"){activeDownloads=Math.Max(0,activeDownloads-1);lastAuto=job;if(job.State=="incomplete"&&monitoring&&job.Path!=null&&job.Attempt<3&&waiting.Count<2048)waiting[job.Path]=new Candidate{Path=job.Path,Attempt=job.Attempt+1,Seen=DateTime.UtcNow};if(job.State=="completed"&&job.Skipped==0&&job.Path!=null){if(scanned.Count>=2048)scanned.Clear();scanned[job.Path]=job.Stamp;}}
  string detail=failure??(job.State=="cancelled"?"Scan stopped. ":job.State=="incomplete"?"Scan incomplete; some files could not be inspected. ":"Scan completed. ")+job.Checked+" files checked · "+job.Skipped+" skipped · "+job.Findings+" findings · "+job.Quarantined+" quarantined.";
  if(notify!=null&&new[]{"quick","full","selected"}.Contains(job.Mode))notify(detail);
  if(job.Mode!="download"||job.Findings==0||job.Skipped>0)Add(job.State=="failed"||job.State=="incomplete"||job.Skipped>0?"warning":"scan",job.Mode=="download"?"Download checked":job.Mode=="quick"?"Quick scan":job.Mode=="full"?"Full scan":job.Mode=="reconcile"?"Recent downloads checked":"Selected scan",detail);
 }
 void Add(string kind,string title,string detail){events.Insert(0,new{id=Guid.NewGuid().ToString("N"),at=DateTime.UtcNow.ToString("o"),kind,title,detail});if(events.Count>60)events.RemoveAt(60);}
 object ScanState(Job job){return job==null?new{state="idle",mode="",bytesChecked=0L,currentFile="",checkedFiles=0L,skippedFiles=0L,findingCount=0L,quarantined=0L,elapsedSeconds=0}:new{state=job.State,mode=job.Mode,bytesChecked=job.Bytes,currentFile=job.CurrentFile,checkedFiles=job.Checked,skippedFiles=job.Skipped,findingCount=job.Findings,quarantined=job.Quarantined,elapsedSeconds=new[]{"queued","scanning","paused","stopping"}.Contains(job.State)?Math.Max(0,(int)(DateTime.UtcNow-job.Started).TotalSeconds):0};}
 internal object Snapshot(){lock(gate){long now=DateTimeOffset.UtcNow.ToUnixTimeSeconds();return new{supported=true,available,engine="Sentinel",monitoring,queue=waiting.Count+activeDownloads,error,updateError,signatures,definitionsAt=builtAt,definitionsFresh=builtAt>0&&now>=builtAt&&now-builtAt<=7*86400,scan=ScanState(manual??lastAuto),autoscan=new{active=activeDownloads,last=ScanState(lastAuto)},events=events.ToArray(),findings=findings.ToArray(),scope="Startup folders and the last seven days of Downloads for Quick Scan. Full Scan checks internal fixed drives. Automatic download checks run while Sentinel is open."};}}
 Job Submit(string mode,string[] roots,Candidate candidate){lock(gate){if(!available||runtime==null)throw new InvalidOperationException("The scanner is still preparing or needs a restart.");var job=new Job{Id=Guid.NewGuid().ToString("N"),Mode=mode,Attempt=candidate==null?0:candidate.Attempt,Path=candidate==null?null:candidate.Path,Stamp=candidate==null?null:candidate.Length+":"+candidate.Written.Ticks+":"+builtAt};jobs.Add(job.Id,job);try{runtime.Write(new{op="scan",id=job.Id,mode,roots});}catch{jobs.Remove(job.Id);throw;}return job;}}
 internal void Scan(string requested){if(requested!="quick"&&requested!="full")throw new InvalidOperationException("Invalid scan type.");lock(gate){if(disposed)throw new InvalidOperationException("Sentinel is closing.");if(manual!=null&&new[]{"queued","scanning","paused","stopping"}.Contains(manual.State))throw new InvalidOperationException("A scan is already running.");var roots=new List<string>();if(requested=="quick"){foreach(string path in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Startup),Environment.GetFolderPath(Environment.SpecialFolder.CommonStartup),downloads})if(Directory.Exists(path)&&NativeScanPolicy.NoLinks(path))roots.Add(path);}else{foreach(var drive in DriveInfo.GetDrives())if(!drive.Name.StartsWith("E:",StringComparison.OrdinalIgnoreCase)&&drive.DriveType==DriveType.Fixed&&drive.IsReady)roots.Add(drive.RootDirectory.FullName);}if(roots.Count==0)throw new InvalidOperationException("No supported scan locations available.");manual=Submit(requested,roots.ToArray(),null);error="";}}
 internal void ScanSelected(string path){lock(gate){if(manual!=null&&new[]{"queued","scanning","paused","stopping"}.Contains(manual.State))throw new InvalidOperationException("A scan is already running.");if(path==null||path.StartsWith("E:",StringComparison.OrdinalIgnoreCase)||!NativeScanPolicy.NoLinks(path))throw new InvalidOperationException("The selected location is unavailable or linked.");manual=Submit("selected",new[]{path},null);}}
 internal void Cancel(){lock(gate){if(manual!=null&&new[]{"queued","scanning","paused","stopping"}.Contains(manual.State)&&runtime!=null){runtime.Write(new{op="cancel",id=manual.Id});manual.State="stopping";manual.CancelRequested=DateTime.UtcNow;}}}
 internal void SetMonitoring(bool enabled){lock(gate){if(disposed)return;if(enabled&&watcher==null){if(string.IsNullOrEmpty(downloads))throw new InvalidOperationException("Downloads unavailable.");watcher=new FileSystemWatcher(downloads){IncludeSubdirectories=true,NotifyFilter=NotifyFilters.FileName|NotifyFilters.LastWrite|NotifyFilters.Size,InternalBufferSize=32768};watcher.Created+=(s,e)=>Arrived(e.FullPath);watcher.Changed+=(s,e)=>Arrived(e.FullPath);watcher.Renamed+=(s,e)=>Arrived(e.FullPath);watcher.Error+=(s,e)=>{lock(gate){scanned.Clear();error="Some download events were missed. Checking recent downloads again.";Reconcile();}};watcher.EnableRaisingEvents=true;}if(!enabled){if(watcher!=null){watcher.Dispose();watcher=null;}waiting.Clear();foreach(var job in jobs.Values.Where(j=>(j.Mode=="download"||j.Mode=="reconcile")).ToArray())runtime.Write(new{op="cancel",id=job.Id});}monitoring=enabled;using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey("Software\\Sentinel\\Protection"))key.SetValue("DownloadMonitoring",enabled?1:0,Microsoft.Win32.RegistryValueKind.DWord);if(enabled&&available)Reconcile();}}
 void Arrived(string path){if(!NativeScanPolicy.Candidate(downloads,path))return;lock(gate){if(disposed||!monitoring)return;scanned.Remove(path);if(waiting.Count>=2048&&!waiting.ContainsKey(path)){error="Download queue is full. Recent downloads will be checked again.";return;}waiting[path]=new Candidate{Path=path,Seen=DateTime.UtcNow};}}
 void Reconcile(){if(disposed||!monitoring||!available||jobs.Values.Any(j=>j.Mode=="reconcile"))return;lastReconcile=DateTime.UtcNow;Submit("reconcile",new[]{downloads},null);}
 void Tick(object unused){lock(gate){if(disposed||checking)return;if(!available){if(!initializing&&(DateTime.UtcNow-lastRestart).TotalSeconds>60){if(runtime!=null)runtime.Dispose();StartRuntime();}return;}if(jobs.Values.Any(j=>new[]{"scanning","stopping"}.Contains(j.State)&&(DateTime.UtcNow-j.ProgressAt).TotalSeconds>240)){runtime.Dispose();Failed("The scan stopped responding. Unfinished files were not marked clean.");return;}if(jobs.Count==0&&(DateTime.UtcNow-lastRestart).TotalHours>=12){generation++;runtime.Dispose();StartRuntime();return;}if(!monitoring)return;if(jobs.Count==0&&(DateTime.UtcNow-lastReconcile).TotalMinutes>=30)Reconcile();checking=true;try{foreach(var item in waiting.Values.ToArray()){if(activeDownloads>=4)break;if(jobs.Values.Any(j=>(j.Mode=="download"||j.Mode=="reconcile")&&string.Equals(j.Path,item.Path,StringComparison.OrdinalIgnoreCase)))continue;try{if(!File.Exists(item.Path)||!NativeScanPolicy.NoLinks(item.Path)){waiting.Remove(item.Path);continue;}var info=new FileInfo(item.Path);if(item.Length!=info.Length||item.Written!=info.LastWriteTimeUtc){item.Length=info.Length;item.Written=info.LastWriteTimeUtc;item.Seen=DateTime.UtcNow;continue;}if((DateTime.UtcNow-item.Seen).TotalSeconds<3)continue;string stamp=item.Length+":"+item.Written.Ticks+":"+builtAt;if(scanned.ContainsKey(item.Path)&&scanned[item.Path]==stamp){waiting.Remove(item.Path);continue;}Submit("download",new[]{item.Path},item);activeDownloads++;waiting.Remove(item.Path);}catch(IOException){}catch(UnauthorizedAccessException){waiting.Remove(item.Path);}}}finally{checking=false;}}}
 public void Dispose(){NativeProtectionRuntime owner;lock(gate){disposed=true;generation++;if(timer!=null)timer.Dispose();if(watcher!=null)watcher.Dispose();owner=runtime;runtime=null;}if(owner!=null)owner.Dispose();}
